-- Deeply nested subqueries, long CTE chains, many joins, expression-heavy queries
SELECT * FROM (SELECT * FROM (SELECT * FROM (SELECT * FROM (SELECT id, name FROM users WHERE active) a WHERE id > 10) b WHERE id < 1000) c ORDER BY id) d LIMIT 10;
SELECT o.id, c.name, p.name, s.name, w.name, r.name FROM orders o JOIN customers c ON c.id = o.customer_id JOIN order_items oi ON oi.order_id = o.id JOIN products p ON p.id = oi.product_id JOIN suppliers s ON s.id = p.supplier_id JOIN warehouses w ON w.id = oi.warehouse_id LEFT JOIN regions r ON r.id = w.region_id LEFT JOIN promotions pr ON pr.id = o.promo_id WHERE o.status <> 'cancelled' AND (pr.id IS NULL OR pr.expires_at > o.created_at);
WITH a AS (SELECT 1 AS x), b AS (SELECT x + 1 AS x FROM a), c AS (SELECT x + 1 AS x FROM b), d AS (SELECT x + 1 AS x FROM c), e AS (SELECT x + 1 AS x FROM d), f AS (SELECT x + 1 AS x FROM e), g AS (SELECT x + 1 AS x FROM f), h AS (SELECT x + 1 AS x FROM g) SELECT * FROM h;
WITH RECURSIVE org AS (SELECT id, manager_id, name, 1 AS lvl FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.id, e.manager_id, e.name, o.lvl + 1 FROM employees e JOIN org o ON e.manager_id = o.id) SELECT * FROM org ORDER BY lvl, name;
WITH RECURSIVE nums (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM nums WHERE n < 10) SELECT n FROM nums;
SELECT id, (SELECT MAX(amount) FROM payments p WHERE p.order_id = o.id) AS max_payment, (SELECT COUNT(*) FROM order_items i WHERE i.order_id = o.id) AS n_items FROM orders o WHERE o.id IN (SELECT order_id FROM payments WHERE amount > (SELECT AVG(amount) FROM payments));
SELECT * FROM t WHERE (a, b) IN (SELECT x, y FROM s) AND c NOT IN (SELECT z FROM u WHERE z IS NOT NULL);
SELECT * FROM t WHERE a = ANY (SELECT x FROM s) AND b > ALL (SELECT y FROM u);
SELECT * FROM t WHERE EXISTS (SELECT 1 FROM s WHERE s.k = t.k AND NOT EXISTS (SELECT 1 FROM u WHERE u.k = s.k));
SELECT CASE WHEN a > 0 THEN CASE WHEN b > 0 THEN 'pp' ELSE 'pn' END WHEN a < 0 THEN CASE WHEN b > 0 THEN 'np' ELSE 'nn' END ELSE 'z' END AS quadrant FROM t;
SELECT a + b * c - d / e % f AS arith, (a + b) * (c - d) AS paren, -a AS neg, NOT a AS notv, a || b || c AS cat FROM t;
SELECT * FROM t WHERE a = 1 OR b = 2 AND c = 3 OR NOT d = 4 AND (e = 5 OR f = 6);
SELECT * FROM t WHERE x BETWEEN 1 AND 10 AND y NOT BETWEEN 5 AND 6 AND z IS DISTINCT FROM w AND q IS NOT DISTINCT FROM r;
SELECT a, b FROM t1 UNION SELECT a, b FROM t2 UNION ALL SELECT a, b FROM t3 ORDER BY a LIMIT 5;
(SELECT a FROM t1 ORDER BY a LIMIT 3) UNION ALL (SELECT a FROM t2 ORDER BY a DESC LIMIT 3);
SELECT a FROM t1 WHERE a IN (SELECT a FROM t2 UNION SELECT a FROM t3);
SELECT x.* FROM (SELECT a, b FROM t1 UNION ALL SELECT a, b FROM t2) x JOIN (SELECT a FROM t3 INTERSECT SELECT a FROM t4) y ON x.a = y.a;
WITH base AS (SELECT user_id, event_ts, event_name, payload FROM raw.events WHERE event_ts >= DATEADD(day, -30, CURRENT_DATE())), sessions AS (SELECT user_id, event_ts, SUM(is_new) OVER (PARTITION BY user_id ORDER BY event_ts) AS session_id FROM (SELECT user_id, event_ts, IFF(DATEDIFF(minute, LAG(event_ts) OVER (PARTITION BY user_id ORDER BY event_ts), event_ts) > 30, 1, 0) AS is_new FROM base)), agg AS (SELECT user_id, session_id, MIN(event_ts) AS s_start, MAX(event_ts) AS s_end, COUNT(*) AS events FROM sessions GROUP BY 1, 2) SELECT user_id, COUNT(*) AS sessions, AVG(DATEDIFF(second, s_start, s_end)) AS avg_secs FROM agg GROUP BY user_id HAVING COUNT(*) > 1;
SELECT t.id, t.payload:a::string AS a, f1.value:b::string AS b, f2.value::number AS c FROM tbl t, LATERAL FLATTEN(input => t.payload:list) f1, LATERAL FLATTEN(input => f1.value:nums) f2 WHERE f2.value::number > 0;
SELECT u.id, ARRAY_AGG(DISTINCT p.name) WITHIN GROUP (ORDER BY p.name) AS products, SUM(oi.qty * oi.price) AS spend FROM users u JOIN orders o ON o.user_id = u.id JOIN order_items oi ON oi.order_id = o.id JOIN products p ON p.id = oi.product_id GROUP BY u.id QUALIFY RANK() OVER (ORDER BY SUM(oi.qty * oi.price) DESC) <= 10;
SELECT COALESCE(a.id, b.id) AS id, a.v AS a_v, b.v AS b_v FROM a FULL JOIN b ON a.id = b.id WHERE COALESCE(a.v, '') <> COALESCE(b.v, '');
SELECT CAST(x AS NUMBER(10, 2)), x::varchar(10), TRY_CAST(y AS INT), CAST('2024-01-01' AS DATE), EXTRACT(year FROM d), EXTRACT(epoch_second FROM ts), DATE_PART(dayofweek, d) FROM t;
SELECT SUBSTR(s, 2, 3), LEFT(s, 2), RIGHT(s, 2), TRIM(s), LTRIM(s, ' '), REPLACE(s, 'a', 'b'), POSITION('a' IN s), CHARINDEX('a', s), LENGTH(s), UPPER(s), INITCAP(s), LPAD(s, 5, '0'), REGEXP_REPLACE(s, '[0-9]+', ''), REGEXP_SUBSTR(s, '[a-z]+', 1, 1, 'i'), CONTAINS(s, 'x'), STARTSWITH(s, 'a') FROM t;
SELECT INTERVAL '1 day' + CURRENT_TIMESTAMP(), CURRENT_DATE() - INTERVAL '3 months', ts + INTERVAL '2 hours 30 minutes' FROM t;
SELECT ROUND(x, 2), CEIL(x), FLOOR(x), ABS(x), MOD(x, 3), POWER(x, 2), SQRT(x), LN(x), GREATEST(a, b, c), LEAST(a, b), DIV0(a, b), SIGN(x), TRUNC(x, 1) FROM t;
SELECT * FROM a, b, c WHERE a.id = b.id AND b.id = c.id;
SELECT * FROM (SELECT 1 AS a) AS x(a) JOIN (SELECT 2 AS b) AS y(b) ON TRUE;
SELECT 1 AS "select", 2 AS "from", 3 AS "Group By";
SELECT t."ID", t."Name" FROM "DB"."SCH"."T" AS t;
SELECT a FROM t ORDER BY a NULLS LAST, b DESC NULLS FIRST;
SELECT a FROM t LIMIT 10 OFFSET 5;
SELECT a FROM t FETCH FIRST 5 ROWS ONLY;
SELECT a FROM t OFFSET 5 ROWS FETCH NEXT 10 ROWS ONLY;
SELECT * FROM t1 JOIN t2 ON t1.id = t2.id AND t1.ts BETWEEN t2.start_ts AND t2.end_ts;
SELECT * FROM t1 ASOF JOIN t2 MATCH_CONDITION (t1.ts >= t2.ts) ON t1.sym = t2.sym;
SELECT * FROM t1 LEFT JOIN LATERAL (SELECT * FROM t2 WHERE t2.k = t1.k ORDER BY ts DESC LIMIT 1) l ON TRUE;
SELECT ARRAY_AGG(x) WITHIN GROUP (ORDER BY y DESC) FROM t;
SELECT SUM(x) OVER (PARTITION BY a, b ORDER BY c DESC, d ASC ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM t;
SELECT SUM(x) OVER (ORDER BY ts RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM t;
SELECT a FROM t WHERE b = 'x' AND c IN (1, 2, 3) AND d LIKE 'a%' ESCAPE '\\' AND e IS NULL;
